var<private> global: u32;
var<private> global_1: vec4<f32> = vec4<f32>(0f, 0f, 0f, 1f);

fn VSMain_1() {
    let _e8 = global;
    let _e17 = ((vec2<f32>(f32(((_e8 << bitcast<u32>(1u)) & 2u)), f32((_e8 & 2u))) * 2f) - vec2<f32>(1f, 1f));
    global_1 = vec4<f32>(_e17.x, _e17.y, 0f, 1f);
    return;
}

@vertex 
fn VSMain(@builtin(vertex_index) param: u32) -> @builtin(position) vec4<f32> {
    global = param;
    VSMain_1();
    let _e3 = global_1;
    return _e3;
}

