var opaqueColor: texture_2d<f32>;
@group(0) @binding(2) 
var accumulation: texture_2d<f32>;
@group(0) @binding(3) 
var revealage: texture_2d<f32>;
var<private> global: vec4<f32>;
var<private> outvarSV_Target: vec4<f32>;

fn PSMain_1() {
    let _e9 = global;
    let _e11 = vec2<i32>(_e9.xy);
    let _e15 = vec3<i32>(_e11.x, _e11.y, 0i).xy;
    let _e16 = textureLoad(opaqueColor, _e15, 0i);
    let _e18 = textureLoad(accumulation, _e15, 0i);
    let _e19 = textureLoad(revealage, _e15, 0i);
    let _e29 = mix(_e16.xyz, (_e18.xyz / vec3(max(_e18.w, 0.000001f))), vec3((1f - clamp(_e19.x, 0f, 1f))));
    outvarSV_Target = vec4<f32>(_e29.x, _e29.y, _e29.z, 1f);
    return;
}

@fragment 
fn PSMain(@builtin(position) param: vec4<f32>) -> @location(0) vec4<f32> {
    global = param;
    PSMain_1();
    let _e3 = outvarSV_Target;
    return _e3;
}
